    @Test
    fun cset64_1() {
        val cases = LinterCases("cset64")
        cases.pass("")
        cases.pass("1")
        cases.pass("12")
        cases.pass("123")
        cases.pass("12=")
        cases.pass("1==")
        cases.fail("===", Gs1ErrorCode.INVALID_CSET64_PADDING, 0, 3)
        cases.fail("123=", Gs1ErrorCode.INVALID_CSET64_PADDING, 3, 1)
        cases.fail("12==", Gs1ErrorCode.INVALID_CSET64_PADDING, 2, 2)
        cases.fail("1===", Gs1ErrorCode.INVALID_CSET64_PADDING, 1, 3)
        cases.fail("1234=", Gs1ErrorCode.INVALID_CSET64_PADDING, 4, 1)
        cases.fail("123==", Gs1ErrorCode.INVALID_CSET64_PADDING, 3, 2)
        cases.fail("12===", Gs1ErrorCode.INVALID_CSET64_PADDING, 2, 3)
        cases.fail("12====", Gs1ErrorCode.INVALID_CSET64_PADDING, 2, 4)
        cases.fail("12=====", Gs1ErrorCode.INVALID_CSET64_PADDING, 2, 5)
        cases.fail("12======", Gs1ErrorCode.INVALID_CSET64_PADDING, 2, 6)
        cases.fail("=23", Gs1ErrorCode.INVALID_CSET64_CHARACTER, 0, 1)
        cases.fail("1=3", Gs1ErrorCode.INVALID_CSET64_CHARACTER, 1, 1)
        cases.fail("=234", Gs1ErrorCode.INVALID_CSET64_CHARACTER, 0, 1)
        cases.fail("1=34", Gs1ErrorCode.INVALID_CSET64_CHARACTER, 1, 1)
        cases.fail("12=4", Gs1ErrorCode.INVALID_CSET64_CHARACTER, 2, 1)
        cases.pass("")
        cases.pass("ABCDEFGHIJKLMNOPQRSTUVWXYZ")
        cases.pass("abcdefghijklmnopqrstuvwxyz")
        cases.pass("0123456789-_")
        cases.fail("ABC ", Gs1ErrorCode.INVALID_CSET64_CHARACTER, 3, 1)
        cases.fail("AB C", Gs1ErrorCode.INVALID_CSET64_CHARACTER, 2, 1)
        cases.fail(" ABC", Gs1ErrorCode.INVALID_CSET64_CHARACTER, 0, 1)
        cases.fail("\u0001", Gs1ErrorCode.INVALID_CSET64_CHARACTER, 0, 1)
        cases.fail("\u0002", Gs1ErrorCode.INVALID_CSET64_CHARACTER, 0, 1)
        cases.fail("\u0003", Gs1ErrorCode.INVALID_CSET64_CHARACTER, 0, 1)
