    @Test
    fun csetnumeric() {
        val cases = LinterCases("csetnumeric")
        cases.pass("")
        cases.pass("0")
        cases.pass("9")
        cases.pass("00")
        cases.pass("09")
        cases.pass("90")
        cases.pass("99")
        cases.pass("0123456789")
        cases.fail("/", Gs1ErrorCode.NON_DIGIT_CHARACTER, 0, 1)
        cases.fail(":", Gs1ErrorCode.NON_DIGIT_CHARACTER, 0, 1)
        cases.fail("a0", Gs1ErrorCode.NON_DIGIT_CHARACTER, 0, 1)
        cases.fail("0a", Gs1ErrorCode.NON_DIGIT_CHARACTER, 1, 1)
        cases.verify()
    }

    @Test
    fun csum() {
        val cases = LinterCases("csum")
        cases.fail("", Gs1ErrorCode.TOO_SHORT_FOR_CHECK_DIGIT, 0, 0)
        cases.pass("02345673")
        cases.fail("12345673", Gs1ErrorCode.INCORRECT_CHECK_DIGIT, 7, 1)
        cases.pass("416000336108")
        cases.fail("416000336109", Gs1ErrorCode.INCORRECT_CHECK_DIGIT, 11, 1)
        cases.pass("1234567890128")
        cases.fail("1234567890129", Gs1ErrorCode.INCORRECT_CHECK_DIGIT, 12, 1)
        cases.pass("12345678901231")
        cases.fail("12345678901232", Gs1ErrorCode.INCORRECT_CHECK_DIGIT, 13, 1)
        cases.pass("123456789012345675")
        cases.fail("123456789012345670", Gs1ErrorCode.INCORRECT_CHECK_DIGIT, 17, 1)
        cases.fail(" 23456789012345675", Gs1ErrorCode.NON_DIGIT_CHARACTER, 0, 1)
        cases.fail("12345678 012345675", Gs1ErrorCode.NON_DIGIT_CHARACTER, 8, 1)
        cases.fail("12345678901234567 ", Gs1ErrorCode.NON_DIGIT_CHARACTER, 17, 1)
        cases.verify()
    }

    @Test
    fun csumalpha() {
        val cases = LinterCases("csumalpha")
        cases.fail("", Gs1ErrorCode.TOO_SHORT_FOR_CHECK_PAIR, 0, 0)
        cases.fail("2", Gs1ErrorCode.TOO_SHORT_FOR_CHECK_PAIR, 0, 1)
        cases.pass("22")
        cases.fail("33", Gs1ErrorCode.INCORRECT_CHECK_PAIR, 0, 2)
        cases.pass("!22")
        cases.pass("!!22")
        cases.pass("1987654Ad4X4bL5ttr2310c2K")
        cases.fail("1987654Ad4X4bL5ttr2310cXK", Gs1ErrorCode.INCORRECT_CHECK_PAIR, 23, 2)
        cases.fail("1987654Ad4X4bL5ttr2310c2X", Gs1ErrorCode.INCORRECT_CHECK_PAIR, 23, 2)
        cases.pass("12345678901234567890123NT")
        cases.pass("12345_ABCDEFGHIJKLMCP")
        cases.pass("12345_NOPQRSTUVWXYZDN")
        cases.pass("12345_abcdefghijklmN3")
        cases.pass("12345_nopqrstuvwxyzP2")
        cases.pass("12345_!\"%&'()*+,-./LC")
        cases.pass("12345_0123456789:;<=>?62")
        cases.pass("7907665Bm8v2AB")
        cases.pass("97850l6KZm0yCD")
        cases.pass("225803106GSpEF")
        cases.pass("149512464PM+GH")
        cases.pass("62577B8fRG7HJK")
        cases.pass("515942070CYxLM")
        cases.pass("390800494sP6NP")
        cases.pass("386830132uO+QR")
        cases.pass("53395376X1:nST")
        cases.pass("957813138Sb6UV")
        cases.pass("530790no0qOgWX")
        cases.pass("62185314IvwmYZ")
        cases.pass("23956qk1&dB!23")
        cases.pass("794394895ic045")
        cases.pass("57453Uq3qA<H67")
        cases.pass("62185314IvwmYZ")
        cases.pass("0881063PhHvY89")
        cases.pass("00000!HV")
        cases.pass("99999zzzzzzzzzzzzzzzzzzT2")
        cases.pass("99999zzzzzzzzzzzzzzzzzzT2")
        cases.pass("1234567890123456789012345678901234567890123456789012345678901234567890123456789012345678901234567HA")
        cases.pass("zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzUA")
        cases.fail("12345678901234567890123456789012345678901234567890123456789012345678901234567890123456789012345678ZZ", Gs1ErrorCode.TOO_LONG_FOR_CHECK_PAIR_IMPLEMENTATION, 0, 100)
        cases.fail(" 2345678901234567890123NT", Gs1ErrorCode.INVALID_CSET82_CHARACTER, 0, 1)
        cases.fail("123456789 1234567890123NT", Gs1ErrorCode.INVALID_CSET82_CHARACTER, 9, 1)
        cases.fail("1234567890123456789012 NT", Gs1ErrorCode.INVALID_CSET82_CHARACTER, 22, 1)
        cases.fail("12345678901234567890123 T", Gs1ErrorCode.INCORRECT_CHECK_PAIR, 23, 2)
        cases.fail("12345678901234567890123N ", Gs1ErrorCode.INCORRECT_CHECK_PAIR, 23, 2)
        cases.verify()
    }

