    @Test
    fun iban() {
        val cases = LinterCases("iban")
        cases.pass("FR7630006000011234567890189")
        cases.pass("DE91100000000123456789")
        cases.pass("GR9608100010000001234567890")
        cases.pass("MU43BOMM0101123456789101000MUR")
        cases.pass("PK70BANK0000123456789000")
        cases.pass("PL10105000997603123456789123")
        cases.pass("RO09BCYP0000001234567890")
        cases.pass("SA4420000001234567891234")
        cases.pass("ES7921000813610123456789")
        cases.pass("CH5604835012345678009")
        cases.pass("GB98MIDL07009312345678")
        cases.pass("BE71096123456769")
        cases.fail("BE71096123456760", Gs1ErrorCode.INCORRECT_IBAN_CHECKSUM, 2, 2)
        cases.pass("LC14BOSL123456789012345678901234")
        cases.fail("LC14BOSL123456789012345678901230", Gs1ErrorCode.INCORRECT_IBAN_CHECKSUM, 2, 2)
        cases.pass("MT90MALT011000012345MTLCAST001SABC")
        cases.fail("MT90MALT011000012345MTLCAST001SAB0", Gs1ErrorCode.INCORRECT_IBAN_CHECKSUM, 2, 2)
        cases.fail("", Gs1ErrorCode.IBAN_TOO_SHORT, 0, 0)
        cases.fail("B", Gs1ErrorCode.IBAN_TOO_SHORT, 0, 1)
        cases.fail("BE", Gs1ErrorCode.IBAN_TOO_SHORT, 0, 2)
        cases.fail("BE7", Gs1ErrorCode.IBAN_TOO_SHORT, 0, 3)
        cases.fail("BE71", Gs1ErrorCode.IBAN_TOO_SHORT, 0, 4)
        cases.fail("MTXXMALT011000012345MTLCAST001SABCD", Gs1ErrorCode.IBAN_TOO_LONG, 0, 35)
        cases.fail("MTXXMALT011000012345MTLCAST001SABCDE", Gs1ErrorCode.IBAN_TOO_LONG, 0, 36)
        cases.fail("LC14BOSLxx3456789012345678901230", Gs1ErrorCode.INVALID_IBAN_CHARACTER, 8, 1)
        cases.fail("XX361234567890", Gs1ErrorCode.ILLEGAL_IBAN_COUNTRY_CODE, 0, 2)
        cases.verify()
    }

