    @Test
    fun iso3166999() {
        val cases = LinterCases("iso3166999")
        cases.pass("999")
        cases.pass("004")
        cases.pass("894")
        cases.fail("000", Gs1ErrorCode.NOT_ISO3166_OR_999, 0, 3)
        cases.fail("998", Gs1ErrorCode.NOT_ISO3166_OR_999, 0, 3)
        cases.fail("", Gs1ErrorCode.NOT_ISO3166_OR_999, 0, 0)
        cases.fail("9", Gs1ErrorCode.NOT_ISO3166_OR_999, 0, 1)
        cases.fail("99", Gs1ErrorCode.NOT_ISO3166_OR_999, 0, 2)
        cases.fail("9999", Gs1ErrorCode.NOT_ISO3166_OR_999, 0, 4)
        cases.fail("_999", Gs1ErrorCode.NOT_ISO3166_OR_999, 0, 4)
        cases.fail("999_", Gs1ErrorCode.NOT_ISO3166_OR_999, 0, 4)
        cases.fail("AAA", Gs1ErrorCode.NOT_ISO3166_OR_999, 0, 3)
        cases.verify()
    }

