    @Test
    fun pcenc() {
        val cases = LinterCases("pcenc")
        cases.pass("")
        cases.pass("A")
        cases.pass("ABCDEFGHIJKLMNOPQRSTUVWXYZABCDEFGHI")
        cases.pass("%00")
        cases.pass("%FF")
        cases.pass("%Ff")
        cases.pass("%fF")
        cases.pass("%ff")
        cases.fail("%fg", Gs1ErrorCode.INVALID_PERCENT_SEQUENCE, 0, 3)
        cases.fail("%gf", Gs1ErrorCode.INVALID_PERCENT_SEQUENCE, 0, 3)
        cases.fail("%g", Gs1ErrorCode.INVALID_PERCENT_SEQUENCE, 0, 2)
        cases.pass("%20")
        cases.pass("ABC%20")
        cases.pass("ABC%00")
        cases.pass("ABC%FF")
        cases.pass("ABC%ff")
        cases.fail("ABC%fg", Gs1ErrorCode.INVALID_PERCENT_SEQUENCE, 3, 3)
        cases.fail("ABC%gf", Gs1ErrorCode.INVALID_PERCENT_SEQUENCE, 3, 3)
        cases.fail("ABC%g", Gs1ErrorCode.INVALID_PERCENT_SEQUENCE, 3, 2)
        cases.pass("ABC%20XYZ")
        cases.pass("ABC%00XYZ")
        cases.pass("ABC%FFXYZ")
        cases.pass("ABC%ffXYZ")
        cases.fail("ABC%fgXYZ", Gs1ErrorCode.INVALID_PERCENT_SEQUENCE, 3, 3)
        cases.fail("ABC%gfXYZ", Gs1ErrorCode.INVALID_PERCENT_SEQUENCE, 3, 3)
        cases.fail("ABC%gXYZ", Gs1ErrorCode.INVALID_PERCENT_SEQUENCE, 3, 3)
        cases.pass("ABCDEFGHIJKLMNOPQRSTUVWXYZ%00+12345")
        cases.verify()
    }

