    @Test
    fun zero() {
        val cases = LinterCases("zero")
        cases.pass("0")
        cases.pass("00")
        cases.pass("000")
        cases.fail("", Gs1ErrorCode.NOT_ZERO, 0, 0)
        cases.fail("1", Gs1ErrorCode.NOT_ZERO, 0, 1)
        cases.fail("01", Gs1ErrorCode.NOT_ZERO, 0, 2)
        cases.fail("10", Gs1ErrorCode.NOT_ZERO, 0, 2)
        cases.fail("001", Gs1ErrorCode.NOT_ZERO, 0, 3)
        cases.fail("010", Gs1ErrorCode.NOT_ZERO, 0, 3)
        cases.fail("011", Gs1ErrorCode.NOT_ZERO, 0, 3)
        cases.fail("100", Gs1ErrorCode.NOT_ZERO, 0, 3)
        cases.fail("101", Gs1ErrorCode.NOT_ZERO, 0, 3)
        cases.fail("110", Gs1ErrorCode.NOT_ZERO, 0, 3)
        cases.fail("X", Gs1ErrorCode.NOT_ZERO, 0, 1)
        cases.fail("0X", Gs1ErrorCode.NOT_ZERO, 0, 2)
        cases.fail("X0", Gs1ErrorCode.NOT_ZERO, 0, 2)
        cases.verify()
